CREATE EXTENSION IF NOT EXISTS postgis;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions (sid VARCHAR PRIMARY KEY, sess JSON NOT NULL, expire TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_expire_idx ON sessions(expire);
CREATE TABLE IF NOT EXISTS saved_areas (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, geometry geometry(Geometry,4326) NOT NULL, centroid geometry(Point,4326), area_sq_km DOUBLE PRECISION NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS saved_areas_user_idx ON saved_areas(user_id);
CREATE INDEX IF NOT EXISTS saved_areas_geometry_idx ON saved_areas USING GIST(geometry);
CREATE TABLE IF NOT EXISTS analysis_jobs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, saved_area_id UUID REFERENCES saved_areas(id) ON DELETE SET NULL, analysis_type TEXT NOT NULL, geometry geometry(Geometry,4326) NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, comparison_start_date DATE, comparison_end_date DATE, satellite_source TEXT NOT NULL, parameters_json JSONB NOT NULL DEFAULT '{}', status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','PROCESSING','COMPLETED','FAILED','CANCELLED')), progress TEXT, error_code TEXT, error_message TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), started_at TIMESTAMPTZ, completed_at TIMESTAMPTZ, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS analysis_jobs_user_date_idx ON analysis_jobs(user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS analysis_results (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), analysis_job_id UUID NOT NULL UNIQUE REFERENCES analysis_jobs(id) ON DELETE CASCADE, result_json JSONB NOT NULL, area_before DOUBLE PRECISION, area_after DOUBLE PRECISION, change_area DOUBLE PRECISION, change_percentage DOUBLE PRECISION, metadata_json JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS reports (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, analysis_job_id UUID NOT NULL REFERENCES analysis_jobs(id) ON DELETE CASCADE, report_reference TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
